import numpy as np


def q210(missing, invalid, duplicate_rows):
    rates = np.array(
        [np.mean(missing), np.mean(invalid), np.mean(duplicate_rows)], float
    )
    return {
        "missing_rate": rates[0],
        "invalid_rate": rates[1],
        "duplicate_rate": rates[2],
        "quality": float(1 - rates.mean()),
    }
